def _decode(encoded, expected_sha256, what):
    """Decode one embedded asset, refusing bytes that are not what we recorded."""
    raw = base64.b64decode("".join(encoded.split()))
    got = hashlib.sha256(raw).hexdigest()
    if got != expected_sha256:
        raise SystemExit(
            f"materialize: {what} decoded to {got}, expected {expected_sha256}")
    return raw


def materialize(src_tgz, scripts_dir, config_dir):
    """Write the embedded assets out. Called from the verifier Dockerfile."""
    written = []
    if src_tgz:
        dest = pathlib.Path(src_tgz)
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(_decode(PRISTINE_SRC_TGZ_B64, PRISTINE_SRC_SHA256, "src.tgz"))
        written.append(str(dest))
    if scripts_dir:
        base = pathlib.Path(scripts_dir)
        base.mkdir(parents=True, exist_ok=True)
        for name, (digest, encoded) in EMBEDDED_SCRIPTS.items():
            dest = base / name
            dest.write_bytes(_decode(encoded, digest, name))
            dest.chmod(0o755)
            written.append(str(dest))
    if config_dir:
        base = pathlib.Path(config_dir)
        base.mkdir(parents=True, exist_ok=True)
        for name, (digest, encoded) in EMBEDDED_CONFIG.items():
            dest = base / name
            dest.write_bytes(_decode(encoded, digest, name))
            written.append(str(dest))
    for path in written:
        print(f"materialize: wrote {path}")
    return 0


def _materialize_cli(argv):
    ap = argparse.ArgumentParser(
        description="Write the embedded build assets out (image build time).")
    ap.add_argument("--materialize", action="store_true", required=True)
    ap.add_argument("--src-tgz", default="/tmp/src.tgz")
    ap.add_argument("--scripts-dir", default="/scripts")
    ap.add_argument("--config-dir", default="/config")
    args = ap.parse_args(argv)
    return materialize(args.src_tgz, args.scripts_dir, args.config_dir)

# --- END embedded build assets ---


if __name__ == "__main__":
    # --materialize runs at image build time and takes none of the grading
    # arguments, so it is dispatched before the oracle's own parser.
    if "--materialize" in sys.argv:
        sys.exit(_materialize_cli(sys.argv[1:]))
    main()
